      "expVi": "Đáp án đúng: 「おしゃべり（する）、けいさん（する）」(○). Các từ còn lại KHÔNG đi với する: 思い出 (× - động từ là 思い出す), きょうみ (× - dùng 興味がある/持つ), しゅっしん (× - dùng 出身だ), しゅみ (×), じょうだん (× - dùng 冗談を言う, tuyệt đối không nói ×冗談する).",
